 SELECT v INTO STRICT member FROM jsonb_array_elements(ctx.original_manifest->'catalog') v
  WHERE v->>'schema_name'=schema_name AND v->>'table_name'=table_name;
 -- Choose the fixed codec once from the authenticated member. The typed
 -- codec still validates column shape and exact native input/output.
 CASE member->>'data_encoding'
  WHEN 'postgres-text-columns-line.v2' THEN
   decode_function:='immutable_import_text_record'; projection_function:='immutable_import_text_projection';
  WHEN 'postgres-json-text-line.v1' THEN
   decode_function:='immutable_import_decode_record'; projection_function:='immutable_import_row_projection';
  ELSE RAISE EXCEPTION 'Immutable original codec unsupported';
 END CASE;
 target_oid:=to_regclass(format('%I.%I',schema_name,table_name));
 IF target_oid IS NULL THEN RAISE EXCEPTION 'Immutable original relation unavailable';END IF;
