  bool_or(s.original_row_sha256 IS DISTINCT FROM encode(extensions.digest(convert_to(s.original_row_utf8,'UTF8'),'sha256'),'hex'))
  INTO observed,staged_last,stage_digest,raw_changed FROM custodial_dr.immutable_ordinary_import_rows s
  WHERE s.database_oid=ctx.database_oid AND s.backend_pid=ctx.backend_pid AND s.transaction_id=ctx.transaction_id AND s.table_oid=target_oid;
 IF observed<>(member->>'row_count')::bigint OR staged_last<>observed
  THEN RAISE EXCEPTION 'Immutable ordinary staged source incomplete';END IF;
 IF raw_changed THEN RAISE EXCEPTION 'Immutable staged original changed';END IF;
 EXECUTE format('SELECT EXISTS(SELECT 1 FROM custodial_dr.immutable_ordinary_import_rows s CROSS JOIN LATERAL custodial_dr.%I(null::%s,s.original_row_utf8) r WHERE s.database_oid=$1 AND s.backend_pid=$2 AND s.transaction_id=$3 AND s.table_oid=$4 AND custodial_dr.%I(r) IS DISTINCT FROM s.typed_original_text)',
  decode_function,target_oid::regclass,projection_function)
  INTO typed_changed USING ctx.database_oid,ctx.backend_pid,ctx.transaction_id,target_oid;
 IF typed_changed THEN RAISE EXCEPTION 'Immutable staged typed original changed';END IF;
 SELECT string_agg(quote_ident(a.attname),',' ORDER BY a.attnum) INTO columns_sql FROM pg_catalog.pg_attribute a
  WHERE a.attrelid=target_oid AND a.attnum>0 AND NOT a.attisdropped AND a.attgenerated='';
 IF columns_sql IS NULL THEN RAISE EXCEPTION 'Immutable generated-only original unsupported';END IF;
 UPDATE custodial_dr.immutable_private_import_context SET phase='INSERTING_ORDINARY_SET',active_table_oid=target_oid,active_row_sha256=stage_digest
  WHERE database_oid=ctx.database_oid AND backend_pid=ctx.backend_pid AND transaction_id=ctx.transaction_id;
 PERFORM custodial_dr.immutable_import_assert_context();
 -- All rows enter one ordinary statement: PostgreSQL checks immediate self
 -- foreign keys against this complete set. Compare typed TEXT multisets to
 -- preserve multiplicity, numeric precision and ordinary JSON lexical DATA.
 EXECUTE format('WITH inserted AS (INSERT INTO %s AS imported (%s) OVERRIDING SYSTEM VALUE SELECT %s FROM custodial_dr.immutable_ordinary_import_rows s CROSS JOIN LATERAL custodial_dr.%I(null::%s,s.original_row_utf8) r WHERE s.database_oid=$1 AND s.backend_pid=$2 AND s.transaction_id=$3 AND s.table_oid=$4 ORDER BY s.ordinal RETURNING custodial_dr.%I(imported) AS image), actual AS (SELECT image,count(*) n FROM inserted GROUP BY image), expected AS (SELECT typed_original_text image,count(*) n FROM custodial_dr.immutable_ordinary_import_rows WHERE database_oid=$1 AND backend_pid=$2 AND transaction_id=$3 AND table_oid=$4 GROUP BY typed_original_text), mismatch AS ((SELECT * FROM actual EXCEPT ALL SELECT * FROM expected) UNION ALL (SELECT * FROM expected EXCEPT ALL SELECT * FROM actual)) SELECT count(*) FROM mismatch',
  target_oid::regclass,columns_sql,(SELECT string_agg('r.'||quote_ident(a.attname),',' ORDER BY a.attnum) FROM pg_catalog.pg_attribute a WHERE a.attrelid=target_oid AND a.attnum>0 AND NOT a.attisdropped AND a.attgenerated=''),decode_function,target_oid::regclass,projection_function)
  INTO mismatches USING ctx.database_oid,ctx.backend_pid,ctx.transaction_id,target_oid;
 IF mismatches<>0 THEN RAISE EXCEPTION 'Immutable ordinary set readback differs';END IF;
 PERFORM custodial_dr.immutable_import_assert_context();
 UPDATE custodial_dr.immutable_private_import_context SET phase='STAGING',active_table_oid=NULL,active_row_sha256=NULL
  WHERE database_oid=ctx.database_oid AND backend_pid=ctx.backend_pid AND transaction_id=ctx.transaction_id;
 PERFORM custodial_dr.immutable_import_assert_context();
 RETURN actual_witness;
END $fn$;
